/* From Uiverse.io by alexmaracinaru - Tags: card */
.__UIV_SCOPE__ .card {
  width: 190px;
  background: white;
  padding: .4em;
  border-radius: 6px;
}

.__UIV_SCOPE__ .card-image {
  background-color: rgb(236, 236, 236);
  width: 100%;
  height: 130px;
  border-radius: 6px 6px 0 0;
}

.__UIV_SCOPE__ .card-image:hover {
  transform: scale(0.98);
}

.__UIV_SCOPE__ .category {
  text-transform: uppercase;
  font-size: 0.7em;
  font-weight: 600;
  color: rgb(63, 121, 230);
  padding: 10px 7px 0;
}

.__UIV_SCOPE__ .category:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .heading {
  font-weight: 600;
  color: rgb(88, 87, 87);
  padding: 7px;
}

.__UIV_SCOPE__ .heading:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .author {
  color: gray;
  font-weight: 400;
  font-size: 11px;
  padding-top: 20px;
}

.__UIV_SCOPE__ .name {
  font-weight: 600;
}

.__UIV_SCOPE__ .name:hover {
  cursor: pointer;
}
